#[derive(Clone, Debug)]
pub struct DynamicAuthorityClient {
    revalidate: NativeRequestHandle<DynamicAuthorityRevalidate>,
    select: NativeRequestHandle<DynamicAuthoritySelect>,
}
impl DynamicAuthorityClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_requirement(dependencies, requirement_id)
    }

    pub async fn revalidate(&self, request: RevalidateRequest) -> Result<RevalidateResponse, DynamicAuthorityRevalidateInvocationError> {
        self.revalidate.invoke(REVALIDATE_OPERATION, request).await
            .map_err(DynamicAuthorityRevalidateInvocationError::Runtime)?
            .map_err(DynamicAuthorityRevalidateInvocationError::Domain)
    }

    pub async fn revalidate_with_context(&self, context: InvocationContext, request: RevalidateRequest) -> Result<RevalidateResponse, DynamicAuthorityRevalidateInvocationError> {
        self.revalidate.invoke_with_context(REVALIDATE_OPERATION, context, request).await
            .map_err(DynamicAuthorityRevalidateInvocationError::Runtime)?
            .map_err(DynamicAuthorityRevalidateInvocationError::Domain)
    }

    pub async fn select(&self, request: SelectRequest) -> Result<SelectResponse, DynamicAuthoritySelectInvocationError> {
        self.select.invoke(SELECT_OPERATION, request).await
            .map_err(DynamicAuthoritySelectInvocationError::Runtime)?
            .map_err(DynamicAuthoritySelectInvocationError::Domain)
    }

    pub async fn select_with_context(&self, context: InvocationContext, request: SelectRequest) -> Result<SelectResponse, DynamicAuthoritySelectInvocationError> {
        self.select.invoke_with_context(SELECT_OPERATION, context, request).await
            .map_err(DynamicAuthoritySelectInvocationError::Runtime)?
            .map_err(DynamicAuthoritySelectInvocationError::Domain)
    }
}

impl CapabilityClient for DynamicAuthorityClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            revalidate: dependencies.one::<DynamicAuthorityRevalidate>()?,
            select: dependencies.one::<DynamicAuthoritySelect>()?,
        })
    }

    fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::from_dependencies(&dependencies)
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for DynamicAuthorityClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    revalidate: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<DynamicAuthorityRevalidate>()?,
                    select: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<DynamicAuthoritySelect>()?,
                    },
                ))
            })
            .collect()
    }

    fn many_from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::many_from_dependencies(&dependencies)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum DynamicAuthorityRevalidateInvocationError {
    Domain(RevalidateError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum DynamicAuthoritySelectInvocationError {
    Domain(SelectError),
    Runtime(RuntimeFailure),
}

#[derive(Clone, Copy, Debug)]
pub struct DynamicAuthorityGuestClient<'a, H: lenso_guest_sdk::HostImports> {
    capability: lenso_guest_sdk::GuestCapability<'a, H>,
}

impl<'a, H: lenso_guest_sdk::HostImports> DynamicAuthorityGuestClient<'a, H> {
    pub fn from_context(context: &'a lenso_guest_sdk::GuestContext<H>) -> Result<Self, lenso_guest_sdk::GuestError<serde_json::Value>> {
        context
            .require(CAPABILITY_ID, DESCRIPTOR_VERSION, &[REVALIDATE_OPERATION, SELECT_OPERATION], &[], &[])
            .map(|capability| Self { capability })
    }

    pub fn revalidate(&self, request: &RevalidateRequest) -> Result<RevalidateResponse, lenso_guest_sdk::GuestError<RevalidateError>> {
        self.capability.request(REVALIDATE_OPERATION, request)
    }

    pub fn select(&self, request: &SelectRequest) -> Result<SelectResponse, lenso_guest_sdk::GuestError<SelectError>> {
        self.capability.request(SELECT_OPERATION, request)
    }
}

#[derive(Debug, Default)]
pub struct DynamicAuthorityJsonCodec;

impl lenso_runtime_codec::JsonCapabilityCodec for DynamicAuthorityJsonCodec {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }

    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }

    fn descriptor_digest(&self) -> &'static str { DESCRIPTOR_DIGEST }

    fn request_operations(&self) -> &'static [&'static str] { &[REVALIDATE_OPERATION, SELECT_OPERATION] }
    fn stream_operations(&self) -> &'static [&'static str] { &[] }
    fn event_operations(&self) -> &'static [&'static str] { &[] }

    fn encode_request(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            REVALIDATE_OPERATION => {
                let value = request.downcast_ref::<RevalidateRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            SELECT_OPERATION => {
                let value = request.downcast_ref::<SelectRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_response(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            REVALIDATE_OPERATION => serde_json::from_value::<RevalidateResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            SELECT_OPERATION => serde_json::from_value::<SelectResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            REVALIDATE_OPERATION => serde_json::from_value::<RevalidateError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            SELECT_OPERATION => serde_json::from_value::<SelectError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_open(&self, operation: &str, _request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn encode_stream_message(&self, operation: &str, _message: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn decode_stream_message(&self, operation: &str, _value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn decode_stream_domain_error(&self, operation: &str, _value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn encode_event(&self, operation: &str, _event: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn invoke_host_request(&self, dependency: lenso_kernel::PluginDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostRequestFuture {
        match operation.as_str() {
            REVALIDATE_OPERATION => {
                let request = serde_json::from_value::<RevalidateRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DynamicAuthorityRevalidate>()?;
                    match handle.invoke_with_context(REVALIDATE_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            SELECT_OPERATION => {
                let request = serde_json::from_value::<SelectRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DynamicAuthoritySelect>()?;
                    match handle.invoke_with_context(SELECT_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }

    fn open_host_stream(&self, _dependency: lenso_kernel::PluginStreamDependencyHandle, operation: String, _request: serde_json::Value, _context: InvocationContext) -> lenso_runtime_codec::JsonHostStreamOpenFuture {
        Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation))))
    }

    fn publish_host_event(&self, _dependency: lenso_kernel::PluginEventDependencyHandle, operation: String, _event: serde_json::Value, _context: InvocationContext) -> futures::future::LocalBoxFuture<'static, Result<(), RuntimeFailure>> {
        Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation))))
    }
}

fn runtime_codec_protocol_failure() -> RuntimeFailure { RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID } }

fn runtime_codec_unknown_operation(operation: &str) -> RuntimeFailure {
    RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }
}
